-- KINGWAY case completion responsibility agreement plan.
-- Creates a new active plan version so previously signed documents remain immutable.
SET NAMES utf8mb4;
START TRANSACTION;

INSERT INTO staff_incentive_plan_versions (
  store_id, version, status,
  bike_sale_amount, bike_handover_amount, bike_followup_amount,
  accessory_rate, repair_inspection_amount,
  effective_from, effective_to, agreement_text,
  created_by_staff_id
)
SELECT
  s.id,
  'KINGWAY-2026-07-R2-RESPONSIBILITY',
  'DRAFT',
  COALESCE(p.bike_sale_amount, 420.00),
  COALESCE(p.bike_handover_amount, 120.00),
  COALESCE(p.bike_followup_amount, 60.00),
  COALESCE(p.accessory_rate, 0.100000),
  COALESCE(p.repair_inspection_amount, 100.00),
  NOW(),
  NULL,
  CONVERT(FROM_BASE64('') USING utf8mb4),
  NULL
FROM stores s
LEFT JOIN staff_incentive_plan_versions p
  ON p.id = (
    SELECT p2.id
    FROM staff_incentive_plan_versions p2
    WHERE p2.store_id = s.id
      AND p2.status = 'ACTIVE'
    ORDER BY p2.effective_from DESC, p2.id DESC
    LIMIT 1
  )
WHERE NOT EXISTS (
  SELECT 1
  FROM staff_incentive_plan_versions existing
  WHERE existing.store_id = s.id
    AND existing.version = 'KINGWAY-2026-07-R2-RESPONSIBILITY'
);

UPDATE staff_incentive_plan_versions old_plan
INNER JOIN staff_incentive_plan_versions new_plan
  ON new_plan.store_id = old_plan.store_id
 AND new_plan.version = 'KINGWAY-2026-07-R2-RESPONSIBILITY'
SET old_plan.status = 'INACTIVE',
    old_plan.effective_to = COALESCE(old_plan.effective_to, NOW())
WHERE old_plan.id <> new_plan.id
  AND old_plan.status = 'ACTIVE';

UPDATE staff_incentive_plan_versions
SET status = 'ACTIVE',
    effective_from = COALESCE(effective_from, NOW()),
    effective_to = NULL,
    agreement_text = CONVERT(FROM_BASE64('') USING utf8mb4)
WHERE version = 'KINGWAY-2026-07-R2-RESPONSIBILITY';

COMMIT;

SELECT
  store_id,
  id AS plan_version_id,
  version,
  status,
  CHAR_LENGTH(agreement_text) AS agreement_text_length,
  LEFT(agreement_text, 40) AS agreement_preview
FROM staff_incentive_plan_versions
WHERE version = 'KINGWAY-2026-07-R2-RESPONSIBILITY'
ORDER BY store_id;
